AOV.SEID_EX = [
  {r:"mind", n:"Скрыть человека", t:"Скрытого можно заметить только критическим успехом Внимательности. Один человек за уровень Измерения; если человек движется — стоимость Измерения втрое. Любое касание другого человека рвёт чары."},
  {r:"mind", n:"Страх", t:"Цель боится чего-то конкретного на Длительность. Действия, сводящие её с предметом страха, получают −10% за уровень Измерения."},
  {r:"mind", n:"Забывчивость", t:"События последних дней (по числу уровня Измерения) вспоминаются только при броске ВОЛ×5. После Длительности память возвращается."},
  {r:"mind", n:"Иллюзия", t:"Цель видит то, чего нет. Измерение 0 — маленький неподвижный предмет; 3 — говорящий, но неподвижный человек; 6 — что угодно."},
  {r:"mind", n:"Туман в голове", t:"−10% ко всем умениям Знания за уровень Измерения."},
  {r:"mind", n:"Внушение", t:"Цель считает внушённое своей мыслью. Измерение — насколько это против её природы; навредить любимому — только на 6."},
  {r:"body", n:"Зуд и жжение", t:"Пример из книги: −10% к умениям Манипуляции за уровень Измерения на Длительность."},
  {r:"body", n:"Облысение / потеря бороды", t:"Полностью волосы выпадают на Измерении 3. Потеря бороды может ударить по Статусу."},
  {r:"body", n:"Пятна на коже", t:"−1 ХАР за уровень Измерения; проходит после Длительности."},
  {r:"body", n:"Немощь", t:"Перемещение −1 за уровень Измерения, или −10% к Манипуляции за уровень, или подобное."},
  {r:"body", n:"Неуклюжесть", t:"10% за уровень Измерения задеть союзника при каждом промахе в атаке."},
  {r:"body", n:"Гнойная рана", t:"Уже имеющаяся рана хуже: −1 ОЗ за уровень Измерения в той же зоне."},
  {r:"body", n:"Исцеление", t:"+1 ОЗ за уровень Измерения, можно распределить по зонам."},
  {r:"body", n:"Оборотничество", t:"0 — собаки лают; 1 — одно чувство зверя; 2 — лицо полузверя, речь со зверями; 3 — перемещение зверя; 4 — его телесная черта; 5 — облик зверя сходного РАЗ; 6 — любой облик."},
  {r:"spirit", n:"Слиться с духом-зверем", t:"Невидим для не имеющих Ясновидения, говорит с духами. Взаимодействие с вещами — по Измерению."},
  {r:"spirit", n:"Дух в животное", t:"Дух практика вселяется в живое животное."},
  {r:"spirit", n:"Лишить покоя и защиты", t:"Дух-зверь цели теряется: −10% за уровень Измерения ко всем умениям Мистики и Восприятия."},
  {r:"spirit", n:"Беспокойство", t:"Цель тянет из дома: Измерение — как далеко, Длительность — как надолго. Каждый день бросок ВОЛ×5, иначе уходит."},
  {r:"spirit", n:"Духовная связь", t:"Практик чувствует сильные эмоции цели в пределах Дистанции; 20% за уровень Измерения на чувственный образ."},
  {r:"spirit", n:"Сосуд богов", t:"Бог высшего Поклонения говорит через практика; 10% за уровень Измерения открыть новую подсказку."},
  {r:"weave", n:"Стихийное бедствие", t:"Местность подвержена бедствиям: первое через 1D6 часов. Внутри построек — бросок ЛОВ×5 или урон = Измерению в случайную зону."},
  {r:"weave", n:"Густой туман", t:"−10% к Внимательности за уровень Измерения."},
  {r:"weave", n:"Сглаз", t:"Шанс неудачи у одной цели в одной группе умений +3% за уровень Измерения, пока цель в пределах Дистанции."},
  {r:"weave", n:"Гадание", t:"Сначала ритуал, затем Предназначение: к обычным +20% добавляется +5% за уровень Измерения."},
  {r:"weave", n:"Погода", t:"Каждый уровень Измерения сдвигает погоду на ступень по таблице сезона (с. 76)."},
  {r:"weave", n:"Вплести чары в ткань", t:"За уровень Измерения: ±1 ОЗ зоне, которую закрывает ткань, или ±10% к связанному умению. Работает в пределах Дистанции."}
];

